private void absorbEntity(Mob e) {
        int toAdd = 1;
        if (xpTank.getFluid().getAmount() >= MEMORY_ESSENCE_AMOUNT) {
            toAdd += e.level().random.nextInt(3) + 1;
        }
        ISpawnerCoreStats newStats = inv.getStats().addAmount(e.getType(), toAdd);
        if (newStats != inv.getStats()) {
            e.discard();
            if (toAdd > 1) {
                xpTank.drain(MEMORY_ESSENCE_AMOUNT, IFluidHandler.FluidAction.EXECUTE);
            }
            ItemStack stack = inv.getStackInSlot(0);
            stack.set(ModDataComponents.SPAWNER_CORE_STATS, newStats);
            inv.setStackInSlot(0, stack);
            e.level().playSound(null, worldPosition, SoundEvents.PORTAL_TRIGGER, SoundSource.BLOCKS, 1f, 2f);
            if (level instanceof ServerLevel) {
                ((ServerLevel) level).sendParticles(ParticleTypes.CLOUD, e.getX(), e.getY() + 0.5, e.getZ(), 5, 0, 1, 0, 0);
            }
        }
    }

private void scanForEntities() {
        targetEntities.clear();
        targetEntities.addAll(nonNullLevel().getEntitiesOfClass(Mob.class, rangeManager.getExtentsAsAABB(), this::isApplicable));
    }

private boolean isApplicable(LivingEntity e) {
        return e.getType().is(PneumaticCraftTags.EntityTypes.VACUUM_TRAP_WHITELISTED) ||
                !e.getType().is(Tags.EntityTypes.BOSSES)
                && !(e instanceof DroneEntity)
                && !(e instanceof Warden)
                && !(e instanceof TamableAnimal t && t.isTame())
                && !e.getType().is(PneumaticCraftTags.EntityTypes.VACUUM_TRAP_BLACKLISTED);
    }

@Override
    public StarbyState onDestinationReached() {
        this.starbuncle.getNavigation().stop();

        IItemHandler iItemHandler = behavior.getItemCapFromTile(targetPos, behavior.TO_DIRECTION_MAP.get(targetPos.hashCode()));
        if (iItemHandler == null) {
            starbuncle.addGoalDebug(this, new DebugEvent("NoItemHandler", "No item handler at " + targetPos.toString()));
            return nextState;
        }

        boolean didDeposit = depositStack(iItemHandler);
        if (!didDeposit) {
            starbuncle.setBackOff(5 + starbuncle.level.random.nextInt(20));
            starbuncle.addGoalDebug(this, new DebugEvent("no_room", targetPos.toString()));
            return nextState;
        }

        OpenChestEvent event = new OpenChestEvent((ServerLevel) starbuncle.level, targetPos, 20);
        event.open();
        EventQueue.getServerInstance().addEvent(event);

        ItemStack left = starbuncle.getHeldStack();
        starbuncle.addGoalDebug(this, new DebugEvent("stored_item", "successful at " + targetPos.toString() + "set stack to " + left.getCount() + "x " + left.getHoverName().getString()));
        boolean fetchPassengerStack = left.isEmpty();
        while (fetchPassengerStack) {
            fetchPassengerStack = false;
            starbuncle.getNextItemFromPassengers();
            if (!starbuncle.getHeldStack().isEmpty()) {
                fetchPassengerStack = depositStack(iItemHandler) && starbuncle.getHeldStack().isEmpty();
            }
        }
        return nextState;
    }

