public boolean depositStack(IItemHandler iItemHandler) {
        ItemStack oldStack = new ItemStack(starbuncle.getHeldStack().getItem(), starbuncle.getHeldStack().getCount());
        ItemStack left = ItemHandlerHelper.insertItemStacked(iItemHandler, starbuncle.getHeldStack(), false);
        starbuncle.setHeldStack(left);
        return !left.equals(oldStack);
    }

public void open() {
        try {
            if (level.getBlockEntity(pos) instanceof ChestBlockEntity chestBlockEntity) {
                fakePlayer.level = level;
                fakePlayer.containerCounter = fakePlayer.containerCounter % 100 + 1;
                fakePlayer.setPos(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5);
                fakePlayer.containerMenu = chestBlockEntity.createMenu(fakePlayer.containerCounter, fakePlayer.inventory, fakePlayer);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

public void attemptClose() {
        try {
            if (level.getBlockEntity(pos) instanceof ChestBlockEntity) {
                fakePlayer.level = level;
                fakePlayer.setPos(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5);
                fakePlayer.containerMenu = null;
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

@Override
    public void tick(boolean serverSide) {
        duration--;
        if (duration <= 0) {
            attemptClose();
        }
    }

@Override
    public boolean isExpired() {
        return duration <= 0;
    }

@Override
    public void tick() {
        if (isDecorative && level.isClientSide) {
            makeParticle(color.nextColor((int) level.getGameTime() * 20), color.nextColor((int) level.getGameTime() * 20 + 200), 10);
            return;
        }


        if (level.isClientSide && ritual != null) {
            makeParticle(ritual.getCenterColor(), ritual.getOuterColor(), ritual.getParticleIntensity());
        }
        if (isOff)
            return;
        if (ritual != null) {

            if (ritual.getContext().isDone) {
                ritual.onEnd();
                ritual = null;
                getLevel().playSound(null, getBlockPos(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0f, 1.0f);
                getLevel().setBlock(getBlockPos(), getLevel().getBlockState(getBlockPos()).setValue(RitualBrazierBlock.LIT, false), 3);
                updateBlock();
                return;
            }
            if (!ritual.isRunning() && !level.isClientSide && level.getGameTime() % 5 == 0) {
                level.getEntitiesOfClass(ItemEntity.class, new AABB(getBlockPos()).inflate(1)).forEach(i -> {
                    tryBurnStack(i.getItem());
                });
            }
            if (ritual.consumesSource() && ritual.needsSourceNow()) {
                if (this.sourceBackoff-- <= 0) {
                    int cost = ritual.getSourceCost();
                    if (SourceUtil.takeSourceMultipleWithParticles(getBlockPos(), getLevel(), 6, cost) != null) {
                        ritual.setNeedsSource(false);
                        this.sourceBackoff = 0;
                        updateBlock();
                    } else {
                        this.sourceBackoff = 20;
                        return;
                    }
                } else {
                    return;
                }
            }
            if (this.relayPos != null && level.isLoaded(this.relayPos) && level.getBlockEntity(this.relayPos) instanceof BrazierRelayTile relayTile) {
                ritual.tryTick(relayTile);
                relayTile.ticksToLightOff = 2;
                relayTile.isDecorative = false;
            } else {
                ritual.tryTick(this);
            }
        }
    }

